                                    <svg xmlns="http://www.w3.org/2000/svg" width="7" height="5" viewBox="0 0 7 5" fill="none" class="size-2 transition-colors" :class="sortColumn === 'company' && sortDirection === 'asc' ? 'text-gray-800 dark:text-white' : 'text-gray-300 dark:text-gray-600'">
  <path
    d="M3.45.213a.5.5 0 00-.819 0L.091 3.841a.5.5 0 00.41.787h5.08a.5.5 0 00.41-.787L3.45.213z"
    fill="currentColor"
  />
</svg>                                    <svg xmlns="http://www.w3.org/2000/svg" width="7" height="5" viewBox="0 0 7 5" fill="none" class="size-2 transition-colors" :class="sortColumn === 'company' && sortDirection === 'desc' ? 'text-gray-800 dark:text-white' : 'text-gray-300 dark:text-gray-600'">
  <path
    d="M3.45 4.415a.5.5 0 01-.819 0L.091.787A.5.5 0 01.502 0h5.08a.5.5 0 01.41.787L3.45 4.415z"
    fill="currentColor"
  />
</svg>                                </span>
                            </div>
                        </th>

                        <!-- Arrival Time (sortable) -->
                        <th
                            class="h-11 min-w-48 cursor-pointer px-4 py-3 text-start select-none"
                            @click="handleSort('arrival')"
                        >
                            <div class="flex items-center gap-2">
                                <span class="text-xs font-medium text-gray-500 dark:text-gray-400">
                                    وقت الوصول
                                </span>
                                <span class="flex flex-col gap-0.5" aria-hidden="true">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="7" height="5" viewBox="0 0 7 5" fill="none" class="size-2 transition-colors" :class="sortColumn === 'arrival' && sortDirection === 'asc' ? 'text-gray-800 dark:text-white' : 'text-gray-300 dark:text-gray-600'">
  <path
    d="M3.45.213a.5.5 0 00-.819 0L.091 3.841a.5.5 0 00.41.787h5.08a.5.5 0 00.41-.787L3.45.213z"
    fill="currentColor"
  />
</svg>                                    <svg xmlns="http://www.w3.org/2000/svg" width="7" height="5" viewBox="0 0 7 5" fill="none" class="size-2 transition-colors" :class="sortColumn === 'arrival' && sortDirection === 'desc' ? 'text-gray-800 dark:text-white' : 'text-gray-300 dark:text-gray-600'">
  <path
    d="M3.45 4.415a.5.5 0 01-.819 0L.091.787A.5.5 0 01.502 0h5.08a.5.5 0 01.41.787L3.45 4.415z"
    fill="currentColor"
  />
</svg>                                </span>
                            </div>
                        </th>

                        <!-- Route -->
                        <th class="h-11 min-w-48 px-4 py-3 text-start text-xs font-medium text-gray-500 dark:text-gray-400">
                            المسار
                        </th>

                        <!-- Price -->
                        <th class="h-11 min-w-32 px-4 py-3 text-start text-xs font-medium text-gray-500 dark:text-gray-400">
                            السعر
                        </th>

                        <!-- Status -->
                        <th class="h-11 min-w-32 py-3 pe-5 text-start text-xs font-medium text-gray-500 sm:pe-6 dark:text-gray-400">
                            الحالة
                        </th>
                    </tr>
                </thead>

                <tbody class="divide-y divide-gray-100 dark:divide-gray-800">
                    <template x-if="paginatedRows.length > 0">
                        <template x-for="row in paginatedRows" :key="row.id">
                            <tr class="h-15 transition hover:bg-gray-50/80 dark:hover:bg-white/3">
    <!-- Checkbox + Order ID -->
    <td class="min-w-40 py-3 ps-5 sm:ps-6">
        <div class="flex items-center gap-3">
            <button type="button" role="checkbox" data-slot="checkbox" value="on"
          x-bind:aria-checked="Boolean(Boolean(rowSelection[row.id])) ? 'true' : 'false'"
    x-bind:data-state="Boolean(Boolean(rowSelection[row.id])) ? 'checked' : 'unchecked'"
    x-bind:data-checked="Boolean(Boolean(rowSelection[row.id])) ? '' : null"
        x-on:click="$dispatch('change', { checked: !Boolean(Boolean(rowSelection[row.id])) })"
        :aria-label="`Select order ${row.id}`" @change="handleToggleRowSelect(row.id)" class="peer relative flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-md border border-gray-300 bg-white shadow-theme-xs outline-hidden transition-colors group-has-focus-visible/field-label:ring-0 group-has-disabled/field:opacity-50 after:absolute after:-inset-x-3 after:-inset-y-2 hover:border-brand-500 focus-visible:border-brand-500 focus-visible:ring-3 focus-visible:ring-brand-500/20 disabled:cursor-not-allowed disabled:border-gray-200 disabled:bg-gray-100/50 disabled:shadow-none aria-invalid:border-red-500 aria-invalid:ring-3 aria-invalid:ring-red-500/20 data-checked:border-brand-500 data-checked:bg-brand-500 data-checked:text-white data-checked:hover:border-brand-600 data-checked:hover:bg-brand-600 aria-invalid:data-checked:border-red-500 aria-invalid:data-checked:bg-red-500 data-disabled:data-checked:border-gray-200 data-disabled:data-checked:bg-transparent data-disabled:data-checked:text-gray-300 dark:border-gray-700 dark:bg-gray-900 dark:hover:border-brand-400 dark:focus-visible:border-brand-400 dark:focus-visible:ring-brand-500/30 dark:disabled:border-gray-800 dark:disabled:bg-gray-800/50 dark:aria-invalid:border-red-500/50 dark:aria-invalid:ring-red-500/40 dark:data-checked:border-brand-500 dark:data-checked:bg-brand-500 dark:data-checked:hover:border-brand-600 dark:data-checked:hover:bg-brand-600 dark:data-disabled:data-checked:border-gray-800 dark:data-disabled:data-checked:text-gray-600">
    <span data-state="checked" data-slot="checkbox-indicator"
        x-show="Boolean(Boolean(rowSelection[row.id]))"
        style="display: none;"
        class="grid place-content-center text-current transition-none [&>svg]:size-3 **:stroke-[1.5px]">
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" >
    <path d="M20 6L9 17l-5-5" />
  </svg>
    </span>
</button>
            <span class="text-sm font-normal text-gray-700 dark:text-gray-300" x-text="row.id"></span>
        </div>
    </td>

    <!-- Category -->
    <td class="min-w-36 px-4 py-3 text-sm font-normal whitespace-nowrap text-gray-800 dark:text-white/90" x-text="row.categoryLabel"></td>

    <!-- Company -->
    <td class="min-w-40 px-4 py-3 text-sm font-normal whitespace-nowrap text-gray-700 dark:text-gray-400" x-text="row.company"></td>

    <!-- Arrival Time -->
    <td class="min-w-48 px-4 py-3 text-sm font-normal whitespace-nowrap text-gray-700 dark:text-gray-400" x-text="row.arrival"></td>

    <!-- Route -->
    <td class="min-w-48 px-4 py-3 text-sm font-normal whitespace-nowrap text-gray-700 dark:text-gray-400" x-text="row.route"></td>

    <!-- Price -->
    <td class="min-w-32 px-4 py-3 text-sm font-normal whitespace-nowrap text-gray-700 dark:text-gray-400" x-text="row.price"></td>

    <!-- Status Badge -->
    <td class="min-w-32 py-3 pe-5 sm:pe-6">
        <span
            data-slot="badge"
            data-variant="light"
            :data-color="row.statusColor"
            data-size="sm"
            :class="row.badgeClasses"
        >
            <span class="text-xs" x-text="row.statusLabel"></span>
        </span>
    </td>
</tr>                        </template>
                    </template>
                    <template x-if="paginatedRows.length === 0">
                        <tr>
                            <td colspan="7" class="py-12 text-center text-sm text-gray-500 dark:text-gray-400">
                                No activities found.
                            </td>
                        </tr>
                    </template>
                </tbody>
            </table></div>
    </div>
</div>
    </div>

    <!-- Table Footer - Pagination -->
    <div class="flex flex-col gap-4 border-t border-gray-200 px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-6 dark:border-gray-800">
    <!-- Showing X to Y of Z -->
    <div class="text-sm font-medium text-gray-500 dark:text-gray-400">
        عرض
        <span class="text-gray-800 dark:text-white/90" x-text="totalCount === 0 ? 0 : startRow + 1"></span>
        إلى
        <span class="text-gray-800 dark:text-white/90" x-text="Math.min(endRow, totalCount)"></span>
        من
        <span class="text-gray-800 dark:text-white/90" x-text="totalCount"></span>
    </div>

    <!-- Mobile Pagination (< sm) -->
    <div class="flex w-full items-center justify-between sm:hidden">
        <span class="text-sm font-medium text-gray-700 dark:text-gray-400" x-text="`${currentPage}/${totalPages}`"></span>

        <div class="flex items-center gap-2">
            <a
                href="#"
                aria-label="Previous page"
                data-slot="pagination-link"
                :class="prevClass()"
                :aria-disabled="currentPage <= 1 ? 'true' : null"
                @click.prevent="goPrevious()"
            >
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="size-5 rtl:rotate-180">
    <path d="M15 18l-6-6 6-6" />
  </svg>
            </a>
            <a
                href="#"
                aria-label="Next page"
                data-slot="pagination-link"
                :class="nextClass()"
                :aria-disabled="currentPage >= totalPages ? 'true' : null"
                @click.prevent="goNext()"
            >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="size-5 rtl:rotate-180">
    <path d="M9 18l6-6-6-6" />
  </svg>
            </a>
        </div>
    </div>

    <!-- Desktop Pagination (>= sm) -->
    <div class="hidden sm:flex sm:items-center sm:justify-end">
        <nav role="navigation" aria-label="pagination" data-slot="pagination"  class="flex mx-0 w-auto justify-end"><ul data-slot="pagination-content"  class="flex items-center gap-1.5"><li data-slot="pagination-item"><a
                        href="#"
                        aria-label="Previous page"
                        data-slot="pagination-link"
                        :class="prevClass()"
                        :aria-disabled="currentPage <= 1 ? 'true' : null"
                        @click.prevent="goPrevious()"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="size-5 rtl:rotate-180">
    <path d="M15 18l-6-6 6-6" />
  </svg>
                    </a></li>

                <template x-for="(p, index) in pages" :key="p === '...' ? `ellipsis-${index}` : p">
                    <li data-slot="pagination-item"><template x-if="p === '...'">
                            <span class="flex size-10 items-center justify-center rounded-[10px] border border-gray-300 bg-white font-medium text-gray-700 shadow-theme-xs dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300">
                                ...
                            </span>
                        </template>
                        <template x-if="p !== '...'">
                            <a
                                href="#"
                                data-slot="pagination-link"
                                :data-active="currentPage === Number(p) ? 'true' : 'false'"
                                :aria-current="currentPage === Number(p) ? 'page' : null"
                                :class="linkClass(Number(p))"
                                @click.prevent="goTo(Number(p))"
                                x-text="Number(p)"
                            ></a>
                        </template></li>
                </template>

                <li data-slot="pagination-item"><a
                        href="#"
                        aria-label="Next page"
                        data-slot="pagination-link"
                        :class="nextClass()"
                        :aria-disabled="currentPage >= totalPages ? 'true' : null"
                        @click.prevent="goNext()"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="size-5 rtl:rotate-180">
    <path d="M9 18l6-6-6-6" />
  </svg>
                    </a></li></ul></nav>
    </div>
</div></div>
    </div>
            </div>
        </div>

    </div>

</body>


</html>
